package com.fitbox.app;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.BitmapFactory;
import android.media.AudioAttributes;
import android.net.Uri;
import android.os.Build;
import org.json.*;
import java.text.SimpleDateFormat;
import java.util.*;

/** Local, opt-in Android reminders. No network, location or exact-alarm permission. */
public final class NudgeScheduler {
    private static final String PREF="fitbox-nudges";
    private static final int BASE=8200,COUNT=32;
    private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}
    public static boolean allowed(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)&&((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled();}
    private static void cancelAlarms(Context c){AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int i=0;i<COUNT;i++){PendingIntent pending=PendingIntent.getBroadcast(c,BASE+i,new Intent(c,NudgeReceiver.class),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(pending!=null){alarms.cancel(pending);pending.cancel();}}prefs(c).edit().remove("payload").apply();}
    public static void cancel(Context c){cancelAlarms(c);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancelAll();}
    public static void schedule(Context c,String json){if(json==null||json.length()>50000)return;try{JSONObject payload=new JSONObject(json);cancelAlarms(c);if(!payload.optBoolean("enabled")||!allowed(c))return;prefs(c).edit().putString("payload",json).apply();JSONArray events=payload.optJSONArray("events");if(events==null)return;AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int i=0;i<Math.min(COUNT,events.length());i++){JSONObject event=events.getJSONObject(i);long at=localTime(event);if(at<=System.currentTimeMillis())continue;Intent intent=new Intent(c,NudgeReceiver.class).putExtra("event",event.toString()).putExtra("scheduledAt",at);PendingIntent pending=PendingIntent.getBroadcast(c,BASE+i,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);}}catch(JSONException ignored){cancel(c);}}
    public static void restore(Context c){String json=prefs(c).getString("payload",null);if(json!=null)schedule(c,json);}
    public static void nextComeback(Context c,JSONObject previous){try{JSONObject payload=new JSONObject(prefs(c).getString("payload","{}"));if(!payload.optBoolean("enabled")||System.currentTimeMillis()-payload.optLong("lastOpenedAt")<7L*86400000)return;JSONObject event=new JSONObject(previous.toString());Calendar date=Calendar.getInstance();date.setTimeInMillis(localTime(previous));date.add(Calendar.DAY_OF_YEAR,7);String day=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(date.getTime());event.put("day",day).put("id",day+"-comeback");long at=localTime(event);event.put("at",at).put("expiresAt",at+3600000);JSONArray events=payload.optJSONArray("events");if(events!=null)for(int i=0;i<events.length();i++)if(events.getJSONObject(i).optString("kind").equals("comeback"))events.put(i,event);prefs(c).edit().putString("payload",payload.toString()).apply();Intent intent=new Intent(c,NudgeReceiver.class).putExtra("event",event.toString()).putExtra("scheduledAt",at);PendingIntent pending=PendingIntent.getBroadcast(c,BASE+COUNT-1,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);}catch(JSONException ignored){}}
    private static long localTime(JSONObject e){try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setLenient(false);f.setTimeZone(TimeZone.getDefault());return f.parse(e.getString("day")+" "+e.getString("time")).getTime();}catch(Exception ignored){return e.optLong("at");}}
    private static int minute(String value,int fallback){try{String[] a=value.split(":");return Integer.parseInt(a[0])*60+Integer.parseInt(a[1]);}catch(Exception ignored){return fallback;}}
    private static boolean inside(int value,int start,int end){return start!=end&&(start<end?value>=start&&value<end:value>=start||value<end);}
    private static boolean quiet(JSONObject p){Calendar now=Calendar.getInstance();int m=now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE),day=now.get(Calendar.DAY_OF_WEEK)-1;if(inside(m,minute(p.optString("sleepStart"),1320),minute(p.optString("sleepEnd"),420)))return true;if(p.optBoolean("workQuiet",true)){JSONArray days=p.optJSONArray("workDays");boolean work=false;if(days!=null)for(int i=0;i<days.length();i++)if(days.optInt(i,-1)==day)work=true;if(work&&inside(m,minute(p.optString("workStart"),540),minute(p.optString("workEnd"),1020)))return true;}return false;}
    private static String channel(Context c,String kind,boolean sound){String k=kind.equals("membership")?"membership":kind.equals("rest")?"rest":"workout",id="fitbox-"+k+(sound?"-sound-v1":"-silent-v1");NotificationChannel ch=new NotificationChannel(id,k.equals("membership")?"Membership dates":k.equals("rest")?"Recovery encouragement":"Workout invitations",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Optional FitBox coach reminders. Your quiet hours and system settings apply.");ch.enableVibration(false);if(sound){AudioAttributes audio=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build();ch.setSound(Uri.parse("android.resource://"+c.getPackageName()+"/raw/nudge_"+k),audio);}else ch.setSound(null,null);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);return id;}
    public static void deliver(Context c,JSONObject event,long scheduledAt,boolean test){if(!allowed(c))return;try{JSONObject payload=new JSONObject(prefs(c).getString("payload","{}")),p=payload.optJSONObject("prefs");if(p==null)p=new JSONObject();if(!test){if(!payload.optBoolean("enabled")||quiet(p))return;if(event.optString("kind").equals("followup")&&payload.optLong("lastOpenedAt")>=event.optLong("joinSince"))return;long ttl=Math.max(0,event.optLong("expiresAt")-event.optLong("at"));if(System.currentTimeMillis()>scheduledAt+ttl)return;String today=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),key="count-"+today;int used=prefs(c).getInt(key,0),maximum=Math.max(1,Math.min(2,p.optInt("maxDaily",1)));if(used>=maximum)return;prefs(c).edit().putInt(key,used+1).apply();}
        String kind=event.optString("kind","workout"),route=event.optString("route","home");if(!Arrays.asList("home","program","coach","billing").contains(route))route="home";Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("fitbox-route",route);int id=test?8299:Math.abs(event.optString("id").hashCode()%100000)+1000;PendingIntent tap=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String channel=channel(c,kind,p.optBoolean("sound",true));int icon=kind.equals("membership")?R.drawable.ic_notification_membership:kind.equals("rest")?R.drawable.ic_notification_rest:R.drawable.ic_notification_workout;Notification.Builder builder=new Notification.Builder(c,channel).setSmallIcon(icon).setContentTitle(event.optString("title","FitBox coach")).setContentText(event.optString("body")).setStyle(new Notification.BigTextStyle().bigText(event.optString("body"))).setAutoCancel(true).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).setColor(0xFF087FFF).setContentIntent(tap).setGroup("fitbox-coach");try{BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=8;String trainer=event.optString("trainer").equals("tina")?"tina":"john";try(java.io.InputStream image=c.getAssets().open("assets/design/pixel/coach-"+trainer+"-pixel.png")){builder.setLargeIcon(BitmapFactory.decodeStream(image,null,options));}}catch(Exception ignored){}Notification publicView=new Notification.Builder(c,channel).setSmallIcon(icon).setContentTitle("FitBox").setContentText("A coach reminder is ready.").build();builder.setPublicVersion(publicView);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(id,builder.build());
    }catch(JSONException ignored){}}
    public static void test(Context c){try{JSONObject e=new JSONObject().put("id","test").put("kind","workout").put("route","home").put("trainer","john").put("title","A little encouragement, your way").put("body","This is your FitBox test reminder. Your real reminders respect your sleep and work quiet hours.");deliver(c,e,System.currentTimeMillis(),true);}catch(JSONException ignored){}}
}
